// ===================================================================
// SQL: el closer marcó el lead como calificado en crm.oacg.cl (Twenty).
// Es una conversión OFFLINE: Meta la castea por email/teléfono hasheados
// (action_source "system_generated"), no por cookie de navegador.
//
// Son DOS peldaños: SQL (MEETING) US$ 100 y SQL+ (PROPOSAL) US$ 300. Los dos
// salen como el MISMO evento `SQL` de Meta; lo que cambia es el valor, y
// custom_data.crm_stage dice de cuál de los dos se trata.
// ===================================================================
const crypto = require('crypto');
const hash = (v) => (v ? crypto.createHash('sha256').update(String(v).trim().toLowerCase()).digest('hex') : '');

// ESCALERA de valor del embudo, de menor a mayor. El ORDEN es lo que define
// qué peldaño es superior para el anti-retroceso y para el valor incremental
// de más abajo. Si cambian los montos, se tocan acá y en ningún otro lado.
//
// Un lead que llega a SQL+ vale US$ 300 EN TOTAL, venga del camino que venga:
// si ya pagó su SQL se manda sólo la diferencia (300 - 100 = 200), y si el
// closer lo sube directo desde MQL se mandan los 300 de una. Sumar 100 + 300
// inflaría en US$ 100 cada lead que recorre los dos peldaños.
const MONEDA = 'USD';
const ESCALERA = [
  { escalon: 'sql',      etiqueta: 'SQL',  valor: 100, prefijo: 'sql_',     etapas: ['meeting', 'sql'] },
  { escalon: 'sql_plus', etiqueta: 'SQL+', valor: 300, prefijo: 'sqlplus_', etapas: ['proposal', 'sql+'] },
];

// Twenty manda el VALOR del enum, no la etiqueta que se ve en el tablero:
//   NEW = Nuevo · SCREENING = MQL · PQL = PQL · No contesta
//   MEETING = SQL · PROPOSAL = SQL+ · CUSTOMER = Contrata · NQL = No califica
// Se aceptan también las etiquetas, por si el webhook llega desde otra vista
// o algún día desde otro CRM. Qué etapa cae en qué peldaño vive en
// ESCALERA[].etapas: no hay una segunda lista que se pueda desincronizar.

function norm(s) {
  return String(s == null ? '' : s)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim();
}

function deepFind(obj, claves, validar) {
  const objetivo = claves.map(norm);
  const visto = new Set();
  const cola = [obj];
  while (cola.length) {
    const cur = cola.shift();
    if (!cur || typeof cur !== 'object' || visto.has(cur)) continue;
    visto.add(cur);
    for (const k of Object.keys(cur)) {
      const v = cur[k];
      if (v && typeof v === 'object') { cola.push(v); continue; }
      if (!objetivo.includes(norm(k))) continue;
      const s = String(v == null ? '' : v).trim();
      if (!s) continue;
      if (validar && !validar(s)) continue;
      return s;
    }
  }
  return '';
}

const wh = $json || {};
const body = wh.body || wh;
const headers = wh.headers || {};

// Twenty trae el registro en `record` y el tipo de objeto en `objectMetadata`.
// Se leen por ruta explícita, no con deepFind: el primer `id` que la búsqueda
// en profundidad encuentra es el del objectMetadata, que es el mismo para
// TODAS las oportunidades — con eso el anti-duplicado bloquearía cualquier SQL
// después del primero.
const objeto = norm((body.objectMetadata || {}).nameSingular || '');
const evento = String(body.eventName || '');
const registro = body.record || {};
const tocados = Array.isArray(body.updatedFields) ? body.updatedFields : [];
const fuenteCambio = String((registro.updatedBy || {}).source || '').toUpperCase();

// El webhook del CRM está abierto a todos los objetos: notas, empresas,
// personas. Solo las oportunidades tienen etapa.
if (objeto && objeto !== 'opportunity') {
  return [{ json: { ok: false, motivo: 'objeto_no_es_oportunidad', objeto: objeto } }];
}

// Editar el monto o la fecha de cierre de un negocio que ya está en SQL no es
// un SQL nuevo.
if (/\.updated$/.test(evento) && tocados.length && tocados.indexOf('stage') === -1) {
  return [{ json: { ok: false, motivo: 'no_cambio_la_etapa', campos: tocados } }];
}

const etapa = String(registro.stage || deepFind(body, ['stage', 'etapa', 'status', 'estado', 'pipelinestage', 'dealstage']) || '');
const paso = ESCALERA.find(function (e) { return e.etapas.indexOf(norm(etapa)) !== -1; });
if (!paso) {
  return [{ json: { ok: false, motivo: 'etapa_no_sql', etapa: etapa } }];
}

// El SQL lo declara una persona. Si la etapa la movió una automatización
// (updatedBy.source = API, que es como escribe n8n), no hubo calificación
// humana detrás y no se cuenta como conversión de US$ 100.
if (fuenteCambio === 'API') {
  return [{ json: { ok: false, motivo: 'etapa_movida_por_automatizacion', etapa: etapa } }];
}

const recordId = String(registro.id || deepFind(body, ['recordid', 'opportunityid']) || '');

let email = deepFind(body, ['email', 'primaryemail', 'emails', 'correo'], function (s) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s); }).toLowerCase();
let telefonoRaw = deepFind(body, ['phone', 'primaryphonenumber', 'telefono', 'celular', 'whatsapp']);
let nombre = deepFind(body, ['firstname', 'nombre', 'fullname']);
let apellido = deepFind(body, ['lastname', 'apellido']);

// La oportunidad de Twenty no lleva el contacto encima: solo el
// `pointOfContactId`. Sin email ni teléfono no hay nada que mandarle a Meta,
// así que se va a buscar la persona. Una llamada, y solo cuando ya se sabe que
// esto es un SQL.
const contactoId = String(registro.pointOfContactId || '');
if (!email && contactoId) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://crm.oacg.cl/rest/people/' + contactoId,
      headers: { Authorization: 'Bearer ' + $env.TWENTY_API_KEY },
      json: true,
      timeout: 15000,
    });
    const p = (resp && resp.data && (resp.data.person || resp.data)) || {};
    email = String((p.emails || {}).primaryEmail || '').toLowerCase();
    const tel = String((p.phones || {}).primaryPhoneCallingCode || '') + String((p.phones || {}).primaryPhoneNumber || '');
    if (tel.replace(/\D/g, '')) telefonoRaw = tel;
    nombre = String((p.name || {}).firstName || nombre || '');
    apellido = String((p.name || {}).lastName || apellido || '');
  } catch (e) {
    // Se sigue igual: abajo se decide si con lo que hay alcanza para mandar.
  }
}

const telefono = String(telefonoRaw).replace(/\D/g, '');
if (!email && telefono.length < 10) {
  return [{ json: { ok: false, motivo: 'sin_email_ni_telefono', contacto: contactoId, etapa: etapa } }];
}

// Si el lead trae los identificadores de Meta guardados desde la landing, se
// aprovechan: suben mucho la calidad del match. Los que no vengan acá los
// busca en Baserow el nodo siguiente.
const fbc = deepFind(body, ['fbc', 'metafbc', 'fbclid']);
const fbp = deepFind(body, ['fbp', 'metafbp']);

// Anti-duplicado POR PELDAÑO, no por negocio: la clave lleva el escalón, así
// un mismo negocio manda su SQL y, cuando el closer lo suba, su SQL+. Con la
// clave anterior (sólo el negocio) subir a SQL+ respondía 'sql_ya_enviado' y
// Meta nunca se enteraba del salto.
const estado = $getWorkflowStaticData('global');
estado.sql = estado.sql || {};
const negocio = recordId || hash(email || telefono);
const ahora = Date.now();
for (const k of Object.keys(estado.sql)) {
  if (ahora - estado.sql[k] > 90 * 86400000) delete estado.sql[k];
}

// Migración de la clave vieja. Hasta agosto de 2026 el anti-duplicado guardaba
// el negocio pelado, sin peldaño; esas marcas son SQL ya enviados. Sin
// renombrarlas, el primer salto a SQL+ de cada negocio ya contado cobraría los
// US$ 300 completos en vez del delta de 200.
for (const k of Object.keys(estado.sql)) {
  if (k.indexOf(':') === -1) {
    estado.sql[k + ':sql'] = estado.sql[k];
    delete estado.sql[k];
  }
}

const clave = negocio + ':' + paso.escalon;
if (estado.sql[clave]) {
  return [{ json: { ok: false, motivo: 'sql_ya_enviado', clave: clave } }];
}

// La escalera no baja. Si el negocio ya mandó un peldaño superior, devolverlo a
// SQL en el tablero no vuelve a cobrar: sin esto, un retroceso sumaría otros
// US$ 100 por un lead que ya estaba contado más arriba.
const posicion = ESCALERA.indexOf(paso);
for (let i = posicion + 1; i < ESCALERA.length; i++) {
  if (estado.sql[negocio + ':' + ESCALERA[i].escalon]) {
    return [{ json: { ok: false, motivo: 'escalon_ya_superado', etapa: etapa, enviado: ESCALERA[i].escalon } }];
  }
}

// Valor INCREMENTAL: se manda la diferencia con el peldaño más alto que este
// negocio ya pagó. SQL → SQL+ suma 100 + 200 = 300, exactamente el mismo total
// que un lead que entró directo a SQL+.
let yaPagado = 0;
for (let i = 0; i < posicion; i++) {
  if (estado.sql[negocio + ':' + ESCALERA[i].escalon]) yaPagado = Math.max(yaPagado, ESCALERA[i].valor);
}
const valor = paso.valor - yaPagado;
if (valor <= 0) {
  return [{ json: { ok: false, motivo: 'sin_valor_incremental', etapa: etapa, ya_pagado: yaPagado } }];
}

estado.sql[clave] = ahora;

const eventTime = Math.floor(Date.now() / 1000);
// El peldaño va en el event_id. Con el mismo id Meta deduplicaría el segundo
// evento contra el primero (dedupe por event_name + event_id) y el SQL+ se
// perdería. El prefijo del peldaño base se mantiene idéntico al de antes
// ('sql_<negocio>') para no reenviar como nuevo un SQL que ya salió.
const eventId = paso.prefijo + negocio;

let country = 'CL';
const PREFIJOS = [['595','PY'],['593','EC'],['507','PA'],['506','CR'],['56','CL'],['54','AR'],['52','MX'],['51','PE'],['34','ES'],['1','US']];
for (const par of PREFIJOS) { if (telefono.indexOf(par[0]) === 0) { country = par[1]; break; } }

const emailHash = hash(email || telefono);

const ga4Body = {
  client_id: String((parseInt(emailHash.slice(0, 12), 16) % 1e10) + '.' + eventTime),
  user_id: emailHash,
  timestamp_micros: eventTime * 1000000,
  non_personalized_ads: false,
  events: [{
    name: 'sql',
    params: {
      currency: MONEDA,
      value: valor,
      session_id: String(eventTime),
      engagement_time_msec: 100,
      event_source: 'crm_twenty',
      crm_stage: String(etapa),
      crm_escalon: paso.escalon,
      items: [{
        item_id: 'clinera_' + paso.escalon + '_calificado',
        item_name: 'Clinera ' + paso.etiqueta + ' - Lead calificado por closer',
        item_category: 'crm',
        price: valor,
        quantity: 1,
      }],
    },
  }],
};

return [{ json: {
  ok: true,
  em: hash(email),
  ph: hash(telefono),
  fn: hash(nombre),
  ln: hash(apellido),
  country_hashed: hash(country),
  external_id: hash(email || telefono),
  fbc: fbc,
  fbp: fbp,
  client_user_agent: String(headers['user-agent'] || ''),
  event_time: eventTime,
  event_id: eventId,
  value: valor,
  currency: MONEDA,
  country: country,
  etapa: String(etapa),
  escalon: paso.escalon,
  valor_escalon: paso.valor,
  record_id: String(recordId || ''),
  // En claro solo para buscar en Baserow los identificadores de Meta que la
  // landing guardó al capturar el lead. No salen hacia Meta ni hacia GA4.
  email_plano: email,
  telefono_plano: telefono,
  ga4Body: ga4Body,
} }];

